/**
  *  Generates Data Field (structure field names and array indexes) name Fields.
  */
public class FieldNameFieldFactory : FieldFactory {

	public static readonly string FIELD_NAME = "Field Name";

	public static string ARRAY_INDEX_FORMAT_NAME =
		FormatManager.ARRAY_OPTIONS_GROUP + Options.DELIMITER + "Array Index Format";

	public static class IndexFormat
{	public static readonly IndexFormat decimal = new(10, , );
	public static readonly IndexFormat hex = new(16, , );
	public static readonly IndexFormat octal = new(8, , );
	public static readonly IndexFormat binary = new(2, , );


		int radix;
		string prefix;
		string postfix;

		IndexFormat(int radix, string prefix, string postfix) {
			this.radix = radix;
			this.prefix = prefix;
			this.postfix = postfix;
		}
	}

	private IndexFormat format;

	public FieldNameFieldFactory() : base(FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hlProvider the HightLightStringProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	private FieldNameFieldFactory(FieldFormatModel model, ListingHighlightProvider hlProvider,
			Options displayOptions, ToolOptions fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {
		fieldOptions.registerOption(ARRAY_INDEX_FORMAT_NAME, IndexFormat.decimal, null,
			"Hex or Decimal field offsets for arrays");
		format = fieldOptions.getEnum(ARRAY_INDEX_FORMAT_NAME, IndexFormat.decimal);
	}

	private string getFieldName(Data data) {
		Data parent = data.getParent();
		if (parent != null && (parent.getDataType() is Array)) {
			string indexStr = format.prefix +
				Integer.toString(data.getComponentIndex(), format.radix) + format.postfix;
			return "[" + indexStr + "]";
		}
		return data.getFieldName();
	}

	/* @Override */
	public void fieldOptionsChanged(Options options, string optionName, object oldValue,
			object newValue) {
		base.fieldOptionsChanged(options, optionName, oldValue, newValue);

		if (options.getName().equals(GhidraOptions.CATEGORY_BROWSER_FIELDS)) {
			if (optionName.equals(ARRAY_INDEX_FORMAT_NAME)) {
				format = (IndexFormat) newValue;
				model.update();
			}
		}
	}

	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		object obj = proxy.getObject();
		if (!enabled || !(obj is Data)) {
			return null;
		}
		Data data = (Data) obj;

		string fieldName = getFieldName(data);
		if ((fieldName == null) || (fieldName.length() == 0)) {
			return null;
		}
		AttributedString @as =
			new AttributedString(fieldName, ListingColors.FIELD_NAME, getMetrics());
		FieldElement text = new TextFieldElement(@as, 0, 0);

		return ListingTextField.createSingleLineTextField(this, proxy, text, startX + varWidth,
			width, hlProvider);
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
		object obj = bf.getProxy().getObject();
		if (!(obj is Data)) {
			return null;
		}
		Data data = (Data) obj;
		return new FieldNameFieldLocation(data.getProgram(), data.getMinAddress(),
			data.getComponentPath(), getFieldName(data), col);
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation programLoc) {
		if (!(programLoc is FieldNameFieldLocation)) {
			return null;
		}
		FieldNameFieldLocation loc = (FieldNameFieldLocation) programLoc;
		if (!hasSamePath(bf, loc)) {
			return null;
		}
		return new FieldLocation(index, fieldNum, 0, loc.getCharOffset());

	}

	/* @Override */
	public bool acceptsType(int category, Class<object> proxyObjectClass) {
		if (!typeof(CodeUnit).isAssignableFrom(proxyObjectClass)) {
			return false;
		}
		return (category == FieldFormatModel.OPEN_DATA || category == FieldFormatModel.ARRAY);
	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel, ListingHighlightProvider provider,
			ToolOptions toolOptions, ToolOptions fieldOptions) {
		return new FieldNameFieldFactory(formatModel, provider, toolOptions, fieldOptions);
	}
}
